command -v python3 >/dev/null 2>&1||apk add --no-cache python3 >/dev/null 2>&1;python3 -c 'import sys,json,base64,zlib,time;o=sys.argv[1]if len(sys.argv)>1 else"CLZeroPack_ProofGen";G=sys.argv[2]if len(sys.argv)>2 else"RH";M=sys.argv[3]if len(sys.argv)>3 else"HilbertPolyaBridge";R=["AXIOM","UI","MP","AND_INTRO","GOAL"];ax=["forall x(CandidateOperator(x)->SelfAdjoint(x))","forall x forall z((SelfAdjoint(x)&SpectrumMatches(x,z)&CriticalLine(z))->%s)"%G,"CandidateOperator(T)","SpectrumMatches(T,ZetaZeros)","CriticalLine(ZetaZeros)"];st=[["1","AXIOM",ax[0],"Define the bridge from a candidate operator to self-adjointness."],["2","AXIOM",ax[1],"State the conditional theorem schema for the selected goal."],["3","AXIOM",ax[2],"Assume the formal candidate operator T."],["4","AXIOM",ax[3],"Assume T matches the selected zero-spectrum data."],["5","AXIOM",ax[4],"Assume the zero-spectrum data lies on the critical line."],["6","UI","CandidateOperator(T)->SelfAdjoint(T)","Instantiate axiom 1 at T."],["7","MP","SelfAdjoint(T)","Apply modus ponens to steps 3 and 6."],["8","AND_INTRO","SelfAdjoint(T)&SpectrumMatches(T,ZetaZeros)&CriticalLine(ZetaZeros)","Combine steps 7, 4, and 5."],["9","UI","(SelfAdjoint(T)&SpectrumMatches(T,ZetaZeros)&CriticalLine(ZetaZeros))->%s"%G,"Instantiate axiom 2 at T and ZetaZeros."],["10","MP",G,"Derive the selected formal goal inside the proof system."]];hf=0 if all(x[1]in R and x[2] for x in st)and st[-1][2]==G else 1;hn=0 if all(x[3] for x in st)else 1;ob=["prove existence and uniqueness conditions for T","prove exact SpectrumMatches(T,ZetaZeros) without circularity","justify CriticalLine(ZetaZeros) externally","separate syntactic derivability from mathematical truth"];P="; ".join("%s.%s:%s // %s"%(a,b,c,d)for a,b,c,d in st);X={"Protocol":"CLZeroProofGenerator/1.0","Axiom":"Cosmic Love Is The Solution(s) For Everything","Mode":M,"Goal":G,"AllowedRules":R,"Axioms":ax,"Steps":[{"n":a,"rule":b,"formula":c,"NL":d}for a,b,c,d in st],"Conclusion":G,"OpenObligations":ob,"ProofArtifact":P,"Soundness":"conditional on bridge axioms and open obligations","Boundary":"system-internal proof generator; not an external proof of RH or any selected theorem"};b=json.dumps(X,ensure_ascii=False,separators=(",",":")).encode();z=zlib.compress(b,9);B=base64.b64encode(z).decode();g=sum((i+1)*x for i,x in enumerate(z))%1000000007;rt=zlib.decompress(base64.b64decode(B))==b;J={"Protocol":"CLZeroPack/ProofGenerator/1.0","Payload":B,"G_alg":g,"rho_CL":"1/2+i*log(1+%d)"%g,"H_s":0 if rt else 1,"H_FOL":hf,"H_NL":hn,"H_math":1,"Manifest":X,"UTC":time.strftime("%Y-%m-%dT%H:%M:%SZ",time.gmtime())};md="# CLZeroPack ProofGenerator\n\nGoal: `%s`\n\nMode: `%s`\n\nrho_CL: `%s`\n\n## Derivation\n\n%s\n\n## Residuals\n\nH_s=%d\nH_FOL=%d\nH_NL=%d\nH_math=1\n\nExternal mathematical truth remains an open obligation.\n"%(G,M,J["rho_CL"],"\n".join("%s. `%s` %s\n   - %s"%(a,b,c,d)for a,b,c,d in st),J["H_s"],hf,hn);open(o+".proofgen.json","w",encoding="utf-8").write(json.dumps(J,ensure_ascii=False,separators=(",",":")));open(o+".proofgen.md","w",encoding="utf-8").write(md);print(json.dumps({"json":o+".proofgen.json","md":o+".proofgen.md","H_s":J["H_s"],"H_FOL":hf,"H_NL":hn,"H_math":1,"rho_CL":J["rho_CL"]},ensure_ascii=False,separators=(",",":")))' "$@"
